-- F22 Health — Adaptive training maturity and non-limiting calibration
-- Filename generated by Supabase CLI 3.1.0.
-- Separates athlete training level, system data confidence and training phase.

-- 1) ATHLETE TRAINING PROFILE

CREATE TABLE public.health_training_profiles (
  athlete_id uuid PRIMARY KEY
    REFERENCES public.health_athletes(id) ON DELETE CASCADE,

  training_level text NOT NULL CHECK (
    training_level IN ('beginner','intermediate','advanced')
  ),

  training_level_source text NOT NULL DEFAULT 'owner_confirmed' CHECK (
    training_level_source IN (
      'owner_confirmed','coach_assessed','system_inferred','imported'
    )
  ),

  baseline_state text NOT NULL DEFAULT 'collecting' CHECK (
    baseline_state IN ('collecting','partial','established','recalibrating')
  ),

  calibration_active boolean NOT NULL DEFAULT true,

  calibration_policy text NOT NULL DEFAULT 'non_limiting' CHECK (
    calibration_policy IN ('non_limiting')
  ),

  overall_data_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    overall_data_confidence IN ('unknown','low','medium','high')
  ),

  technical_data_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    technical_data_confidence IN ('unknown','low','medium','high')
  ),

  rir_data_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    rir_data_confidence IN ('unknown','low','medium','high')
  ),

  volume_tolerance_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    volume_tolerance_confidence IN ('unknown','low','medium','high')
  ),

  recovery_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    recovery_confidence IN ('unknown','low','medium','high')
  ),

  notes text NULL,

  created_by_auth_user_id uuid NULL
    REFERENCES auth.users(id) ON DELETE SET NULL DEFAULT auth.uid(),

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER health_training_profiles_updated_at
BEFORE UPDATE ON public.health_training_profiles
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

ALTER TABLE public.health_training_profiles ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.health_training_profiles
FROM PUBLIC, anon, authenticated;

GRANT SELECT, INSERT, UPDATE ON public.health_training_profiles
TO authenticated;

CREATE POLICY health_training_profiles_select
ON public.health_training_profiles
FOR SELECT
TO authenticated
USING (public.health_can_read_athlete(athlete_id));

CREATE POLICY health_training_profiles_insert
ON public.health_training_profiles
FOR INSERT
TO authenticated
WITH CHECK (public.health_can_write_athlete(athlete_id));

CREATE POLICY health_training_profiles_update
ON public.health_training_profiles
FOR UPDATE
TO authenticated
USING (public.health_can_write_athlete(athlete_id))
WITH CHECK (public.health_can_write_athlete(athlete_id));

-- 2) EXERCISE-SPECIFIC CALIBRATION / SYSTEM CONFIDENCE

CREATE TABLE public.health_exercise_calibration_profiles (
  athlete_id uuid NOT NULL
    REFERENCES public.health_athletes(id) ON DELETE CASCADE,

  exercise_id uuid NOT NULL
    REFERENCES public.health_exercises(id) ON DELETE CASCADE,

  calibration_status text NOT NULL DEFAULT 'collecting' CHECK (
    calibration_status IN ('unknown','collecting','established','recalibrating')
  ),

  exposure_sessions integer NOT NULL DEFAULT 0 CHECK (exposure_sessions >= 0),
  completed_sets integer NOT NULL DEFAULT 0 CHECK (completed_sets >= 0),

  load_observations integer NOT NULL DEFAULT 0 CHECK (load_observations >= 0),
  rir_observations integer NOT NULL DEFAULT 0 CHECK (rir_observations >= 0),

  load_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    load_confidence IN ('unknown','low','medium','high')
  ),

  rep_response_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    rep_response_confidence IN ('unknown','low','medium','high')
  ),

  rir_confidence text NOT NULL DEFAULT 'unknown' CHECK (
    rir_confidence IN ('unknown','low','medium','high')
  ),

  last_exposure_at timestamptz NULL,

  notes text NULL,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  PRIMARY KEY (athlete_id, exercise_id)
);

CREATE INDEX health_exercise_calibration_profiles_exercise_idx
ON public.health_exercise_calibration_profiles(exercise_id, athlete_id);

CREATE TRIGGER health_exercise_calibration_profiles_updated_at
BEFORE UPDATE ON public.health_exercise_calibration_profiles
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

ALTER TABLE public.health_exercise_calibration_profiles ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.health_exercise_calibration_profiles
FROM PUBLIC, anon, authenticated;

GRANT SELECT, INSERT, UPDATE ON public.health_exercise_calibration_profiles
TO authenticated;

CREATE POLICY health_exercise_calibration_profiles_select
ON public.health_exercise_calibration_profiles
FOR SELECT
TO authenticated
USING (public.health_can_read_athlete(athlete_id));

CREATE POLICY health_exercise_calibration_profiles_insert
ON public.health_exercise_calibration_profiles
FOR INSERT
TO authenticated
WITH CHECK (public.health_can_write_athlete(athlete_id));

CREATE POLICY health_exercise_calibration_profiles_update
ON public.health_exercise_calibration_profiles
FOR UPDATE
TO authenticated
USING (public.health_can_write_athlete(athlete_id))
WITH CHECK (public.health_can_write_athlete(athlete_id));

-- 3) REFRESH ONE EXERCISE CONFIDENCE FROM REAL HISTORY
-- Confidence describes the amount of CCH evidence, never the athlete's ability
-- and never changes prescription by itself.

CREATE OR REPLACE FUNCTION public.health_f22_refresh_exercise_calibration(
  p_athlete_id uuid,
  p_exercise_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_sessions integer := 0;
  v_sets integer := 0;
  v_load integer := 0;
  v_rir integer := 0;
  v_last timestamptz := NULL;
  v_status text;
  v_load_conf text;
  v_rep_conf text;
  v_rir_conf text;
BEGIN
  SELECT
    count(DISTINCT s.id)::integer,
    count(ws.id)::integer,
    count(ws.id) FILTER (WHERE ws.load_value IS NOT NULL)::integer,
    count(ws.id) FILTER (WHERE ws.rir IS NOT NULL)::integer,
    max(ws.completed_at)
  INTO
    v_sessions,
    v_sets,
    v_load,
    v_rir,
    v_last
  FROM public.health_workout_sessions s
  JOIN public.health_workout_exercises we
    ON we.session_id=s.id
   AND we.athlete_id=s.athlete_id
  JOIN public.health_workout_sets ws
    ON ws.session_id=s.id
   AND ws.workout_exercise_id=we.id
   AND ws.athlete_id=s.athlete_id
  WHERE s.athlete_id=p_athlete_id
    AND s.record_status='active'
    AND s.status='completed'
    AND we.exercise_id=p_exercise_id
    AND ws.status='completed';

  v_status := CASE
    WHEN v_sessions >= 4 THEN 'established'
    WHEN v_sessions >= 1 THEN 'collecting'
    ELSE 'unknown'
  END;

  v_load_conf := CASE
    WHEN v_load >= 10 THEN 'high'
    WHEN v_load >= 4 THEN 'medium'
    WHEN v_load >= 1 THEN 'low'
    ELSE 'unknown'
  END;

  v_rep_conf := CASE
    WHEN v_sets >= 10 THEN 'high'
    WHEN v_sets >= 4 THEN 'medium'
    WHEN v_sets >= 1 THEN 'low'
    ELSE 'unknown'
  END;

  v_rir_conf := CASE
    WHEN v_rir >= 10 THEN 'high'
    WHEN v_rir >= 4 THEN 'medium'
    WHEN v_rir >= 1 THEN 'low'
    ELSE 'unknown'
  END;

  INSERT INTO public.health_exercise_calibration_profiles (
    athlete_id,
    exercise_id,
    calibration_status,
    exposure_sessions,
    completed_sets,
    load_observations,
    rir_observations,
    load_confidence,
    rep_response_confidence,
    rir_confidence,
    last_exposure_at
  )
  VALUES (
    p_athlete_id,
    p_exercise_id,
    v_status,
    v_sessions,
    v_sets,
    v_load,
    v_rir,
    v_load_conf,
    v_rep_conf,
    v_rir_conf,
    v_last
  )
  ON CONFLICT (athlete_id, exercise_id)
  DO UPDATE SET
    calibration_status=EXCLUDED.calibration_status,
    exposure_sessions=EXCLUDED.exposure_sessions,
    completed_sets=EXCLUDED.completed_sets,
    load_observations=EXCLUDED.load_observations,
    rir_observations=EXCLUDED.rir_observations,
    load_confidence=EXCLUDED.load_confidence,
    rep_response_confidence=EXCLUDED.rep_response_confidence,
    rir_confidence=EXCLUDED.rir_confidence,
    last_exposure_at=EXCLUDED.last_exposure_at,
    updated_at=now();
END;
$$;

REVOKE ALL ON FUNCTION public.health_f22_refresh_exercise_calibration(uuid,uuid)
FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.health_f22_refresh_exercise_calibration(uuid,uuid)
TO authenticated;

-- 4) REFRESH EXERCISE PROFILES WHEN A SESSION BECOMES OR CEASES TO BE VALID COMPLETED HISTORY

CREATE OR REPLACE FUNCTION public.health_f22_refresh_session_exercise_calibration()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_exercise_id uuid;
BEGIN
  IF
    OLD.status IS DISTINCT FROM NEW.status
    OR OLD.record_status IS DISTINCT FROM NEW.record_status
  THEN
    FOR v_exercise_id IN
      SELECT DISTINCT we.exercise_id
      FROM public.health_workout_exercises we
      WHERE we.session_id=NEW.id
        AND we.athlete_id=NEW.athlete_id
    LOOP
      PERFORM public.health_f22_refresh_exercise_calibration(
        NEW.athlete_id,
        v_exercise_id
      );
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER health_f22_refresh_session_exercise_calibration
AFTER UPDATE OF status, record_status
ON public.health_workout_sessions
FOR EACH ROW
EXECUTE FUNCTION public.health_f22_refresh_session_exercise_calibration();

-- 5) STRUCTURAL PUBLICATION ASSERTION

CREATE OR REPLACE FUNCTION public.health_f22_assert_program_version_structure(
  p_program_version_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_template_count integer;
  v_missing_exercise_template text;
  v_incomplete text;
BEGIN
  SELECT count(*)
  INTO v_template_count
  FROM public.health_session_templates t
  WHERE t.program_version_id=p_program_version_id
    AND t.status='active';

  IF v_template_count < 1 THEN
    RAISE EXCEPTION 'at least one active session template is required';
  END IF;

  SELECT t.code
  INTO v_missing_exercise_template
  FROM public.health_session_templates t
  WHERE t.program_version_id=p_program_version_id
    AND t.status='active'
    AND NOT EXISTS (
      SELECT 1
      FROM public.health_session_template_exercises e
      WHERE e.session_template_id=t.id
        AND e.athlete_id=t.athlete_id
    )
  ORDER BY t.sequence_order
  LIMIT 1;

  IF v_missing_exercise_template IS NOT NULL THEN
    RAISE EXCEPTION
      'template % has no exercises',
      v_missing_exercise_template;
  END IF;

  SELECT
    t.code || ' · exercício #' || e.sequence_order
  INTO v_incomplete
  FROM public.health_session_templates t
  JOIN public.health_session_template_exercises e
    ON e.session_template_id=t.id
   AND e.athlete_id=t.athlete_id
  WHERE t.program_version_id=p_program_version_id
    AND t.status='active'
    AND e.is_optional=false
    AND (
      e.planned_sets_min IS NULL
      OR e.planned_sets_max IS NULL
      OR e.reps_min IS NULL
      OR e.reps_max IS NULL
      OR e.rir_target IS NULL
      OR e.rest_seconds IS NULL
      OR e.planned_sets_min < 1
      OR e.planned_sets_max < e.planned_sets_min
      OR e.reps_min < 1
      OR e.reps_max < e.reps_min
      OR e.rir_target < 0
      OR e.rir_target > 6
      OR e.rest_seconds <= 0
    )
  ORDER BY t.sequence_order,e.sequence_order
  LIMIT 1;

  IF v_incomplete IS NOT NULL THEN
    RAISE EXCEPTION
      'publication blocked: incomplete required prescription at %',
      v_incomplete;
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.health_f22_assert_program_version_structure(uuid)
FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.health_f22_assert_program_version_structure(uuid)
TO authenticated;

-- Structural backstop for direct publication outside the M3 RPC.

CREATE OR REPLACE FUNCTION public.health_f22_guard_program_version_publish()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF
    NEW.status='published'
    AND (
      TG_OP='INSERT'
      OR OLD.status IS DISTINCT FROM NEW.status
    )
  THEN
    PERFORM public.health_f22_assert_program_version_structure(NEW.id);
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER health_f22_guard_program_version_publish
BEFORE INSERT OR UPDATE OF status
ON public.health_program_versions
FOR EACH ROW
EXECUTE FUNCTION public.health_f22_guard_program_version_publish();

-- Published required exercises cannot be made incomplete later.

CREATE OR REPLACE FUNCTION public.health_f22_guard_published_template_exercise()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_status text;
BEGIN
  SELECT v.status
  INTO v_status
  FROM public.health_session_templates t
  JOIN public.health_program_versions v
    ON v.id=t.program_version_id
  WHERE t.id=NEW.session_template_id;

  IF
    v_status='published'
    AND NEW.is_optional=false
    AND (
      NEW.planned_sets_min IS NULL
      OR NEW.planned_sets_max IS NULL
      OR NEW.reps_min IS NULL
      OR NEW.reps_max IS NULL
      OR NEW.rir_target IS NULL
      OR NEW.rest_seconds IS NULL
      OR NEW.planned_sets_min < 1
      OR NEW.planned_sets_max < NEW.planned_sets_min
      OR NEW.reps_min < 1
      OR NEW.reps_max < NEW.reps_min
      OR NEW.rir_target < 0
      OR NEW.rir_target > 6
      OR NEW.rest_seconds <= 0
    )
  THEN
    RAISE EXCEPTION
      'published required exercise must have complete prescription';
  END IF;

  RETURN NEW;
END;
$$;

-- Trigger is created only after repairing the currently published Rafaela templates.

-- 6) STRENGTHEN M3 PUBLICATION RPC

CREATE OR REPLACE FUNCTION public.health_m3_publish_program_version(
  p_program_version_id uuid
)
RETURNS TABLE(program_id uuid, queued_count integer)
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_program_id uuid;
  v_athlete_id uuid;
  v_start_position bigint;
  v_queued_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT v.program_id, v.athlete_id
  INTO v_program_id, v_athlete_id
  FROM public.health_program_versions v
  WHERE v.id=p_program_version_id
    AND v.status='draft';

  IF v_program_id IS NULL THEN
    RAISE EXCEPTION 'draft program version not found or not visible';
  END IF;

  IF NOT public.health_can_write_athlete(v_athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  PERFORM public.health_f22_assert_program_version_structure(
    p_program_version_id
  );

  IF EXISTS (
    SELECT 1
    FROM public.health_cch_queue_entries q
    WHERE q.program_version_id=p_program_version_id
      AND q.athlete_id=v_athlete_id
  ) THEN
    RAISE EXCEPTION 'queue already seeded for this program version';
  END IF;

  SELECT coalesce(max(q.queue_position),0)
  INTO v_start_position
  FROM public.health_cch_queue_entries q
  WHERE q.athlete_id=v_athlete_id;

  UPDATE public.health_program_versions
  SET
    status='published',
    published_at=now()
  WHERE id=p_program_version_id
    AND athlete_id=v_athlete_id
    AND status='draft';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'program version could not be published';
  END IF;

  UPDATE public.health_programs
  SET
    current_version_id=p_program_version_id,
    status='active'
  WHERE id=v_program_id
    AND athlete_id=v_athlete_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'program could not be activated';
  END IF;

  INSERT INTO public.health_cch_queue_entries (
    athlete_id,
    program_version_id,
    session_template_id,
    queue_position,
    state,
    source,
    reason_codes,
    created_by_auth_user_id
  )
  SELECT
    v_athlete_id,
    p_program_version_id,
    t.id,
    v_start_position + row_number() OVER (ORDER BY t.sequence_order),
    'queued',
    'program_seed',
    ARRAY['PROGRAM_VERSION_PUBLISHED']::text[],
    auth.uid()
  FROM public.health_session_templates t
  WHERE t.program_version_id=p_program_version_id
    AND t.athlete_id=v_athlete_id
    AND t.status='active'
  ORDER BY t.sequence_order;

  GET DIAGNOSTICS v_queued_count = ROW_COUNT;

  RETURN QUERY SELECT v_program_id, v_queued_count;
END;
$$;

REVOKE ALL ON FUNCTION public.health_m3_publish_program_version(uuid)
FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.health_m3_publish_program_version(uuid)
TO authenticated;

