    WHEN 'C1' THEN 'Posterior — tensão'
    WHEN 'D1' THEN 'Glúteos — tensão'
    WHEN 'A2' THEN 'Quadríceps — volume'
    WHEN 'B2' THEN 'Costas — volume'
    WHEN 'C2' THEN 'Posterior — volume'
    WHEN 'D2' THEN 'Glúteos — volume'
