UPDATE public.health_session_template_exercises e
SET
  planned_sets_min=p.sets_min,
  planned_sets_max=p.sets_max,
  reps_min=p.reps_min,
  reps_max=p.reps_max,
  rir_target=p.rir_target,
  rest_seconds=p.rest_seconds,
  prescription_notes=p.note,
  updated_at=now()
FROM public.health_session_templates t,
     prescription p
WHERE e.session_template_id=t.id
  AND e.athlete_id=t.athlete_id
  AND t.athlete_id='671fd7a8-7f0f-4c9f-9e73-89c2caf27692'::uuid
  AND t.program_version_id='3d18b672-7c56-4c86-b8e9-2f5753a1a710'::uuid
  AND t.code=p.code
  AND e.sequence_order=p.exercise_order;

-- Assert the repaired published version is now structurally complete.
SELECT public.health_f22_assert_program_version_structure(
  '3d18b672-7c56-4c86-b8e9-2f5753a1a710'::uuid
);

-- Protect published required exercises from future incomplete mutations.
CREATE TRIGGER health_f22_guard_published_template_exercise
BEFORE INSERT OR UPDATE OF
  planned_sets_min,
  planned_sets_max,
  reps_min,
  reps_max,
  rir_target,
  rest_seconds,
  is_optional
ON public.health_session_template_exercises
FOR EACH ROW
EXECUTE FUNCTION public.health_f22_guard_published_template_exercise();

-- 10) SEED EXERCISE CONFIDENCE FROM EXISTING REAL HISTORY

INSERT INTO public.health_exercise_calibration_profiles (
  athlete_id,
  exercise_id,
  calibration_status,
  exposure_sessions,
  completed_sets,
  load_observations,
  rir_observations,
  load_confidence,
  rep_response_confidence,
  rir_confidence,
  last_exposure_at
)
SELECT
  s.athlete_id,
  we.exercise_id,
  CASE
    WHEN count(DISTINCT s.id) >= 4 THEN 'established'
    ELSE 'collecting'
  END,
  count(DISTINCT s.id)::integer,
  count(ws.id)::integer,
  count(ws.id) FILTER (WHERE ws.load_value IS NOT NULL)::integer,
  count(ws.id) FILTER (WHERE ws.rir IS NOT NULL)::integer,
  CASE
    WHEN count(ws.id) FILTER (WHERE ws.load_value IS NOT NULL) >= 10 THEN 'high'
    WHEN count(ws.id) FILTER (WHERE ws.load_value IS NOT NULL) >= 4 THEN 'medium'
    WHEN count(ws.id) FILTER (WHERE ws.load_value IS NOT NULL) >= 1 THEN 'low'
    ELSE 'unknown'
  END,
  CASE
    WHEN count(ws.id) >= 10 THEN 'high'
    WHEN count(ws.id) >= 4 THEN 'medium'
    WHEN count(ws.id) >= 1 THEN 'low'
    ELSE 'unknown'
  END,
  CASE
    WHEN count(ws.id) FILTER (WHERE ws.rir IS NOT NULL) >= 10 THEN 'high'
    WHEN count(ws.id) FILTER (WHERE ws.rir IS NOT NULL) >= 4 THEN 'medium'
    WHEN count(ws.id) FILTER (WHERE ws.rir IS NOT NULL) >= 1 THEN 'low'
    ELSE 'unknown'
  END,
  max(ws.completed_at)
FROM public.health_workout_sessions s
JOIN public.health_workout_exercises we
  ON we.session_id=s.id
 AND we.athlete_id=s.athlete_id
JOIN public.health_workout_sets ws
  ON ws.session_id=s.id
 AND ws.workout_exercise_id=we.id
 AND ws.athlete_id=s.athlete_id
WHERE s.athlete_id IN (
    '08204502-2e7a-4476-a1ac-6a67b57fa35f'::uuid,
    '671fd7a8-7f0f-4c9f-9e73-89c2caf27692'::uuid
  )
  AND s.record_status='active'
  AND s.status='completed'
  AND ws.status='completed'
GROUP BY s.athlete_id,we.exercise_id
ON CONFLICT (athlete_id,exercise_id)
DO UPDATE SET
  calibration_status=EXCLUDED.calibration_status,
  exposure_sessions=EXCLUDED.exposure_sessions,
  completed_sets=EXCLUDED.completed_sets,
  load_observations=EXCLUDED.load_observations,
  rir_observations=EXCLUDED.rir_observations,
  load_confidence=EXCLUDED.load_confidence,
  rep_response_confidence=EXCLUDED.rep_response_confidence,
  rir_confidence=EXCLUDED.rir_confidence,
  last_exposure_at=EXCLUDED.last_exposure_at,
  updated_at=now();

-- End F22 v1.
